import type { Options } from "@anthropic-ai/claude-agent-sdk";

const headless = { permissionMode: "dontAsk", settingSources: [] } satisfies Options;

export const builder: Options = {
  ...headless,
  allowedTools: ["Read", "Glob", "Grep", "Edit", "Write", "Bash"],
  disallowedTools: ["WebFetch", "WebSearch"],
};

export const reviewer: Options = {
  ...headless,
  tools: ["Read", "Glob", "Grep"],
  allowedTools: ["Read", "Glob", "Grep"],
};

import { query } from "@anthropic-ai/claude-agent-sdk";
import { builder } from "./roles.js";

const prompt = "List the files in this folder. Then create hello.txt containing hi. Say what happened.";
const options = { ...builder, model: "claude-haiku-5-5", allowedTools: ["Read", "Glob", "Grep"] };

for await (const msg of query({ prompt, options })) {
  if (msg.type === "result") {
    console.log("denied:", msg.permission_denials.map((d) => d.tool_name));
    if (msg.subtype === "success") console.log("said:", msg.result);
  }
}

export const tester: Options = {
  ...headless,
  allowedTools: ["Read", "Glob", "Grep", "Bash(npm test *)", "Bash(npx vitest *)"],
  disallowedTools: ["Bash(git push *)", "Edit(//etc/**)"],
};

