// src/roles.ts (added)
export const docsWriter: Options = {
  ...headless,
  tools: ["Read", "Glob", "Grep", "Edit", "Write"],
  allowedTools: ["Read", "Glob", "Grep", "Edit(/docs/**)"],
};

// test/roles.test.ts (added)
test("the docs writer may edit docs/ and nothing else", () => {
  const allowed = docsWriter.allowedTools ?? [];
  assert.ok(allowed.includes("Edit(/docs/**)"));
  assert.ok(!allowed.includes("Edit") && !allowed.includes("Write"));
  assert.ok(!(docsWriter.tools as string[]).includes("Bash"));
  assert.equal(docsWriter.permissionMode, "dontAsk");
});
